10,566,1698},h)g[404702]=b({e[11034],404702,1,4,253,"「いいえ、まだ眠くありません。ただ、目が痒いだけです。\n本当です、もうちょっと遊べますよ。\nだから、僕を置いていかないでくださいね？ お姉さま……。」",200047,1,"deco/character/laien_0",302002,60,1775,869,399,939,728,2045,2093,939,728,2045,1101},h)g[404703]=b({e[12034],404703,4,106,254,"「しーっ。今はマジックタイムです、お静かに。一番好きなものを思い浮かべて下さい。…心の声、聞こえましたよ……箱を開けてみて下さい。……中身は僕でした～！　やっぱり、お姉さまが一番好きなのは僕だったんですね！」",200047,2,"deco/character/laien_SD",false,false,1,2021,980,398,1128,236,1677,2614,1128,678,1677},h)g[404704]=b({e[21034],404704,3,24,255,"「ハロウィンのりんごは、色鮮やかなものほど毒があるって言われてるんです。お姉さまがくださるものなら、いただきますけど……あぁ、どんな風に起こしてもらえるんでしょう、ドキドキしちゃいます。」",200047,2,"deco/character/404704",false,false,false,false,false,false,false,false,false,"100,0,1",false,"100,-120,1",1894,891,396,814,699,2545,2369,814,699,2545,1150,1,3769,4173,2104,3618,8000,8500,16000,9667,13000,false,8000},h)g[404801]=b({e[46057],404801,false,121,256,false,200048,false,"deco/character/senchuanlingzi",302002,60,1,false,false,false,34,"1",false,false,false,false,false,false,false,"120,-70,1.02",false,"-30,50,1",false,false,false,"0,40,1","0,40,1",false,false,false,1844,947,393,953,734,2014,2479,953,734,2014,1170,"senchuanlingzi"},h)g[404802]=b({e[12034],404802,1,4,257,"「こ、これが、君が好きな、お日さまの日差しなの？\nもっと日差しを浴びたら、私も君みたいに、お友達がたくさん出来るかな……。\n頑張ってみるから、明日も、一緒にひなたぼっこしたいの。」",200048,1,"deco/character/senchuanlingzi_0",302002,60,1,1839,913,399,766,644,2468,2556,766,644,2468,1229,false,false,false,false,false,false,false,false,false,false,false,false,"senchuanlingzi_0"},h)g[404803]=b({e[21034],404803,9,84,258,"「こ、これは……いい夢を見せるための魔法陣なの。お泊りに来てもらった友達は君が初めてだから、その…いい夢を見てもらいたいな……って……」",200048,2,"deco/character/404803",false,false,false,false,false,false,false,"1",false,false,false,"0,-140,1",1953,950,380,1005,562,2128,1997,1005,639,2128,false,1,3475,5000,1801,3207,8000,13333,6333,3166,10000,false,8000,"senchuanlingzi_sy"},h)g[404804]=b({e[12034],404804,12,48,259,"「私と一緒に踊りたい、の……？　嬉しいけど、踊るってことは、両手が君の体に触れることになっちゃうの。君に不幸が移るのが怖いの……。君はずっと、この世で一番幸運な人でいて欲しいの。」",200048,2,"deco/characte